-- SlotWise: Database Initialization Script for MySQL
-- Run this script in MySQL Workbench or via MySQL CLI:
-- mysql -u root -p < database-setup.sql

CREATE DATABASE IF NOT EXISTS slotwise_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

USE slotwise_db;

-- Tables will be automatically managed and created by Hibernate (spring.jpa.hibernate.ddl-auto=update).
-- The following DDL statements reflect the relational schema generated by Spring Data JPA:

CREATE TABLE IF NOT EXISTS users (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    full_name VARCHAR(100) NOT NULL,
    email VARCHAR(150) NOT NULL UNIQUE,
    password VARCHAR(255) NOT NULL,
    role VARCHAR(30) NOT NULL,
    created_at DATETIME NOT NULL
);

CREATE TABLE IF NOT EXISTS resources (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    name VARCHAR(150) NOT NULL,
    type VARCHAR(30) NOT NULL,
    description TEXT,
    location VARCHAR(150) NOT NULL,
    capacity INT,
    active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at DATETIME NOT NULL
);

CREATE TABLE IF NOT EXISTS bookings (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    user_id BIGINT NOT NULL,
    resource_id BIGINT NOT NULL,
    booking_date DATE NOT NULL,
    start_time TIME NOT NULL,
    end_time TIME NOT NULL,
    purpose VARCHAR(255) NOT NULL,
    status VARCHAR(30) NOT NULL,
    created_at DATETIME NOT NULL,
    CONSTRAINT fk_booking_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    CONSTRAINT fk_booking_resource FOREIGN KEY (resource_id) REFERENCES resources(id) ON DELETE RESTRICT
);

-- Index for fast conflict resolution queries
CREATE INDEX idx_booking_conflict ON bookings (resource_id, booking_date, status, start_time, end_time);
